import math, bisect, heapq, random, sys, itertools
sys.setrecursionlimit(2 * 10 ** 5)
input = sys.stdin.readline

def slope(x1, y1, x2, y2):
	if x2 - x1 == 0:
		return 'inf'
	return float(y2 - y1) / (x2 - x1)
t = int(input())
for i in range(t):
	n = int(input())
	x = []
	y = []
	c = 0
	for k in range(n):
		s = [int(j) for j in input().split()]
		x.append(s[0])
		y.append(s[1])
	for j in range(0, n):
		m = {}
		for k in range(0, n):
			if k == j:
				continue
			if slope(x[j], y[j], x[k], y[k]) in m:
				m[slope(x[j], y[j], x[k], y[k])] += 1
				continue
			m[slope(x[j], y[j], x[k], y[k])] = 1
		for k in m:
			if k == 'inf':
				if 0 in m:
					c += m[0] * m[k]
				continue
			if k == 0:
				if 'inf' in m:
					c += m['inf'] * m[k]
				continue
			if 1 / k * -1 in m:
				c += m[1 / k * -1] * m[k]
	print(c // 2)
